package dev.slithergoh.pixelmonradar.client;

import com.pixelmonmod.pixelmon.api.pokemon.Pokemon;import com.pixelmonmod.pixelmon.api.extensions.PixelmonPlayerExtension;import com.pixelmonmod.pixelmon.api.pokedex.PokedexStorage;import com.pixelmonmod.pixelmon.entities.pixelmon.PixelmonEntity;import net.minecraft.client.Minecraft;import net.minecraft.world.phys.AABB;import java.util.*;
public final class PokemonScanner{private PokemonScanner(){}public static List<PokemonInfo>scan(){Minecraft mc=Minecraft.getInstance();if(mc.level==null||mc.player==null)return List.of();PokedexStorage dex=((PixelmonPlayerExtension)mc.player).getPokedexNow();double r=RadarSettings.pokemonRange;AABB box=mc.player.getBoundingBox().inflate(r);List<PokemonInfo>out=new ArrayList<>();for(PixelmonEntity entity:mc.level.getEntitiesOfClass(PixelmonEntity.class,box)){Pokemon p=entity.getPokemon();if(p==null)continue;if(RadarSettings.hideOwnedPokemon&&entity.getOwnerUUID()!=null)continue;boolean seen=dex!=null&&dex.hasSeen(p),caught=dex!=null&&dex.hasCaught(p);if(RadarSettings.uncaughtOnly&&caught)continue;if(RadarSettings.unseenOnly&&seen)continue;boolean shiny=p.isShiny(),legendary=p.isLegendary(true),mythical=p.isMythical(),ub=p.isUltraBeast(),paradox=p.isParadox(),boss=entity.isBossPokemon();PokemonInfo info=new PokemonInfo(entity.getId(),entity.getLocalizedName(),p.getPokemonLevel(),mc.player.distanceTo(entity),entity.blockPosition(),p.getSprite(),shiny,legendary,mythical,ub,paradox,boss,String.valueOf(p.getGender()),p.getFormName(),p.getPaletteName(),boss&&entity.getBossTier()!=null?String.valueOf(entity.getBossTier()):"",seen,caught);boolean any=RadarSettings.shinyOnly||RadarSettings.rareOnly||RadarSettings.filterLegendary||RadarSettings.filterMythical||RadarSettings.filterUltraBeast||RadarSettings.filterParadox||RadarSettings.filterBoss;if(any){boolean matches=(RadarSettings.shinyOnly&&shiny)||(RadarSettings.rareOnly&&info.rare())||(RadarSettings.filterLegendary&&legendary)||(RadarSettings.filterMythical&&mythical)||(RadarSettings.filterUltraBeast&&ub)||(RadarSettings.filterParadox&&paradox)||(RadarSettings.filterBoss&&boss);if(!matches)continue;}out.add(info);}out.sort(Comparator.comparingDouble(PokemonInfo::distance));return out;}}
